"""Tests du moteur de suivi et du catalogue Elegoo.   python3 -m unittest discover tests"""
import importlib
import json
import os
import sys
import tempfile
import unittest

SRC = os.path.join(os.path.dirname(os.path.dirname(os.path.abspath(__file__))), "src")
sys.path.insert(0, SRC)

GCODE_ORCA = """; HEADER_BLOCK_START
; generated by ElegooSlicer
; total filament weight [g] : 25.06
; HEADER_BLOCK_END
G28
; filament used [mm] = 8402.31
; filament used [g] = 25.06
; filament_type = PLA
"""


class Base(unittest.TestCase):
    def setUp(self):
        self.tmp = tempfile.TemporaryDirectory()
        os.environ["SUIVI_FILAMENT_DATA"] = os.path.join(self.tmp.name, "bobines.json")
        os.environ["SUIVI_FILAMENT_SANS_FENETRE"] = "1"
        import suivi_filament
        self.sf = importlib.reload(suivi_filament)

    def tearDown(self):
        self.tmp.cleanup()

    def gcode(self, texte, nom="piece.gcode"):
        chemin = os.path.join(self.tmp.name, nom)
        with open(chemin, "w", encoding="utf-8") as f:
            f.write(texte)
        return chemin

    def bobine(self, reste=1000, emplacement=1):
        d = self.sf.charger()
        b = {"id": d["prochain_id"], "nom": "Test", "matiere": "PLA", "couleur": "", "poids_net_g": 1000,
             "reste_g": reste, "tare_g": None, "prix_kg": 20, "ajoutee_le": "x"}
        d["bobines"].append(b); d["prochain_id"] += 1; d["actives"][str(emplacement)] = b["id"]
        self.sf.sauver(d)
        return b["id"]


class LectureGcode(Base):
    def test_grammes_orca(self):
        g, infos, _ = self.sf.lire_gcode(self.gcode(GCODE_ORCA))
        self.assertEqual(g, [25.06])
        self.assertEqual(infos["matiere"], "PLA")

    def test_plusieurs_filaments(self):
        g, _, _ = self.sf.lire_gcode(self.gcode(GCODE_ORCA.replace("[g] = 25.06", "[g] = 12.50, 30.00")))
        self.assertEqual(g, [12.5, 30.0])

    def test_calcul_depuis_longueur(self):
        g, _, _ = self.sf.lire_gcode(self.gcode("; filament used [mm] = 1000\n; filament_density = 1.24\n"
                                                "; filament_diameter = 1.75\n"))
        self.assertAlmostEqual(g[0], 2.98, places=2)


class PostTraitement(Base):
    def test_deduction_et_doublon(self):
        ident = self.bobine(reste=1000)
        chemin = self.gcode(GCODE_ORCA)
        self.sf.post_traitement(chemin)
        self.sf.post_traitement(chemin)                 # même G-code ré-exporté : ignoré
        d = self.sf.charger()
        self.assertAlmostEqual(d["bobines"][0]["reste_g"], 1000 - 25.06)
        self.assertEqual(len(d["historique"]), 1)
        self.assertEqual(d["historique"][0]["deductions"], [{"bobine": ident, "g": 25.06}])
        with open(chemin, encoding="utf-8") as f:
            self.assertTrue(f.read().startswith(self.sf.MARQUEUR))

    def test_copie_temporaire_du_slicer(self):
        """Le slicer peut passer une copie « piece.gcode.pp » : elle doit être comptée."""
        import subprocess
        self.bobine(reste=1000)
        chemin = self.gcode(GCODE_ORCA, nom="piece.gcode.pp")
        env = dict(os.environ, SLIC3R_PP_OUTPUT_NAME="/Users/x/Bureau/piece.gcode")
        r = subprocess.run([sys.executable, os.path.join(SRC, "suivi_filament.py"), chemin],
                           env=env, capture_output=True, text=True)
        self.assertEqual(r.returncode, 0, r.stderr)
        d = self.sf.charger()
        self.assertEqual(len(d["historique"]), 1)
        self.assertEqual(d["historique"][0]["tache"], "piece.gcode")
        with open(self.sf.JOURNAL, encoding="utf-8") as f:
            self.assertIn("appel du slicer", f.read())

    def test_gcode_intact(self):
        self.bobine()
        chemin = self.gcode(GCODE_ORCA)
        self.sf.post_traitement(chemin)
        with open(chemin, encoding="utf-8") as f:
            lignes = [l for l in f.read().splitlines() if not l.startswith(self.sf.MARQUEUR)]
        self.assertEqual("\n".join(lignes) + "\n", GCODE_ORCA)


class Catalogue(unittest.TestCase):
    def test_lots_rattaches(self):
        import catalogue_elegoo as ce
        produits = [
            {"title": "PLA Matte", "handle": "pla-matte", "options": [{"name": "Color"}],
             "variants": [{"title": "Matte Black", "option1": "Matte Black", "price": "17.99", "available": True}]},
            {"title": "PLA Matte Filament 10 kg", "handle": "x", "options": [{"name": "PLA Matte (Color)"}],
             "variants": [{"title": "Matte Black", "option1": "Matte Black", "price": "129.99", "available": True}]},
        ]
        cat = ce.construire(produits)
        formats = cat["gammes"][0]["couleurs"][0]["formats"]
        self.assertEqual([f["libelle"] for f in formats], ["Bobine 1 kg", "Lot 10 kg"])
        self.assertEqual(formats[1]["prix_kg"], 13.0)
        self.assertEqual(cat["lots_non_rattaches"], 0)

    def test_instantane_livre(self):
        with open(os.path.join(SRC, "catalogue_elegoo_base.json"), encoding="utf-8") as f:
            cat = json.load(f)
        self.assertGreater(len(cat["gammes"]), 20)
        self.assertEqual(cat["devise"], "EUR")


if __name__ == "__main__":
    unittest.main()
